CREATE TEMP TABLE admitted_cases AS SELECT x->>'name' name,x->'components' c,x->>'receipt_digest' digest FROM admitted_vectors CROSS JOIN LATERAL jsonb_array_elements(v->'valid') z(x);
CREATE FUNCTION pg_temp.admitted_run(c JSONB) RETURNS TEXT LANGUAGE SQL AS $$
 SELECT internal.validate_initial_admitted_proof(c->>'candidate',c->>'input',c->>'configuration',c->>'funding',c->>'outcome',c->>'installation',c->>'protocol',c->>'destination',c->>'mapping',c->>'media_binding',c->>'accounting',c->>'manifest');
$$;
CREATE FUNCTION pg_temp.admitted_hash(d TEXT,t TEXT) RETURNS TEXT LANGUAGE SQL AS $$
 SELECT encode(extensions.digest(convert_to('merian.initial-analysis.'||d||chr(10)||t,'UTF8'),'sha256'),'hex');
$$;
-- Test-only commitment rebuilding lets semantic negatives pass integrity checks.
CREATE FUNCTION pg_temp.admitted_recommit(c JSONB) RETURNS JSONB LANGUAGE PLPGSQL AS $$
DECLARE m JSONB:=(c->>'manifest')::JSONB; k TEXT; d TEXT; path TEXT[];
BEGIN
 FOR k,d IN SELECT * FROM (VALUES('candidate','preparation-candidate.v2'),('input','input.v1'),('configuration','configuration.v1'),('funding','funding.v1'),('outcome','preparation-execution.outcome.v2'),('installation','handoff.installation.v1'),('protocol','handoff.protocol_artifact.v1'),('destination','handoff.destination_backend.v1'),('mapping','handoff.mapping.v2'),('media_binding','handoff.media_binding.v2'),('accounting','handoff.accounting.v1')) z(k,d) LOOP
  path:=ARRAY[CASE WHEN k IN ('mapping','media_binding') THEN 'metadata' ELSE 'proof' END,k];
  m:=jsonb_set(m,path,jsonb_build_object('digest',pg_temp.admitted_hash(d,c->>k),'byte_count',octet_length(c->>k)));
 END LOOP;
 m:=jsonb_set(m,'{metadata_digest}',to_jsonb(pg_temp.admitted_hash('handoff.admitted-metadata.v1',internal.initial_canonical(m->'metadata'))));
 m:=jsonb_set(m,'{proof_digest}',to_jsonb(pg_temp.admitted_hash('handoff.admitted-proof.v1',internal.initial_canonical(m->'proof'))));
 RETURN jsonb_set(c,'{manifest}',to_jsonb(internal.initial_canonical(m)));
END; $$;
CREATE FUNCTION pg_temp.admitted_change(c JSONB,k TEXT,path TEXT[],v JSONB) RETURNS JSONB LANGUAGE SQL AS $$
 SELECT pg_temp.admitted_recommit(jsonb_set(c,ARRAY[k],to_jsonb(internal.initial_canonical(jsonb_set((c->>k)::JSONB,path,v)))));
$$;
-- Positive changes must propagate through original assignment/outcome/media identities.
CREATE FUNCTION pg_temp.admitted_rebind(b JSONB) RETURNS JSONB LANGUAGE PLPGSQL AS $$
DECLARE c JSONB:=(b->>'candidate')::JSONB; cfg JSONB:=(b->>'configuration')::JSONB; a JSONB; o JSONB:=(b->>'outcome')::JSONB;
 input_value JSONB:=(b->>'input')::JSONB; m JSONB:=(b->>'manifest')::JSONB; mapping JSONB:=(b->>'mapping')::JSONB; binding JSONB:=(b->>'media_binding')::JSONB;
 ad TEXT; sd TEXT; od TEXT; k TEXT;
BEGIN
 a:=cfg->'assignment';a:=jsonb_set(a,'{candidate_digest}',to_jsonb(pg_temp.admitted_hash('preparation-candidate.v2',b->>'candidate')));
 a:=jsonb_set(a,'{source_plan_digest}',to_jsonb(pg_temp.admitted_hash('media.source_plan.v1',internal.initial_canonical(c->'source_plan'))));
 cfg:=jsonb_set(cfg,'{assignment}',a);b:=jsonb_set(b,'{configuration}',to_jsonb(internal.initial_canonical(cfg)));
 ad:=pg_temp.admitted_hash('assignment.v2',internal.initial_canonical(a));m:=jsonb_set(m,'{assignment_digest}',to_jsonb(ad));
 o:=jsonb_set(o,'{assignment_digest}',to_jsonb(ad));
 FOREACH k IN ARRAY ARRAY['grant','source_verification','output_manifest','resolved_manifest'] LOOP o:=jsonb_set(o,ARRAY[k,'assignment_digest'],to_jsonb(ad)); END LOOP;
 mapping:=jsonb_set(mapping,'{assignment_digest}',to_jsonb(ad));binding:=jsonb_set(binding,'{assignment_digest}',to_jsonb(ad));
 sd:=pg_temp.admitted_hash('preparation-execution.source_verification.v1',internal.initial_canonical(o->'source_verification'));
 o:=jsonb_set(o,'{grant,source_digest}',to_jsonb(sd));o:=jsonb_set(o,'{output_manifest,source_digest}',to_jsonb(sd));
 o:=jsonb_set(o,'{resolved_manifest,request_digest}',to_jsonb(pg_temp.admitted_hash('preparation-execution.output_manifest.v1',internal.initial_canonical(o->'output_manifest'))));
 b:=jsonb_set(b,'{outcome}',to_jsonb(internal.initial_canonical(o)));od:=pg_temp.admitted_hash('preparation-execution.outcome.v2',b->>'outcome');
 mapping:=jsonb_set(mapping,'{outcome_digest}',to_jsonb(od));binding:=jsonb_set(binding,'{outcome_digest}',to_jsonb(od));
 b:=jsonb_set(b,'{mapping}',to_jsonb(internal.initial_canonical(mapping)));binding:=jsonb_set(binding,'{mapping_digest}',to_jsonb(pg_temp.admitted_hash('handoff.mapping.v2',b->>'mapping')));
 FOREACH k IN ARRAY ARRAY['ordered_descriptions','owner_timeline','admission'] LOOP input_value:=jsonb_set(input_value,ARRAY[k],c#>ARRAY['source_plan',k]); END LOOP;
 b:=jsonb_set(b,'{input}',to_jsonb(internal.initial_canonical(input_value)));binding:=jsonb_set(binding,'{submission_digest}',to_jsonb(pg_temp.admitted_hash('input.v1',b->>'input')));
 b:=jsonb_set(b,'{media_binding}',to_jsonb(internal.initial_canonical(binding)));
 m:=jsonb_set(m,'{descriptions_digest}',to_jsonb(pg_temp.admitted_hash('descriptions.v1',internal.initial_canonical(input_value->'ordered_descriptions'))));m:=jsonb_set(m,'{assets_digest}',a->'asset_manifest_digest');
 RETURN pg_temp.admitted_recommit(jsonb_set(b,'{manifest}',to_jsonb(internal.initial_canonical(m))));
END; $$;
SELECT extensions.is(pg_temp.admitted_run(c),digest,'golden receipt '||name) FROM admitted_cases;
CREATE TEMP TABLE admitted_first AS SELECT (v#>'{valid,0,components}') c FROM admitted_vectors;
SELECT extensions.throws_ok(format('SELECT pg_temp.admitted_run(%L::JSONB)',c-k),'22023','initial_analysis_input_invalid','missing component '||k) FROM admitted_first CROSS JOIN LATERAL jsonb_object_keys(c) k;
SELECT extensions.throws_ok(format('SELECT pg_temp.admitted_run(%L::JSONB)',jsonb_set(c,ARRAY[k],to_jsonb(' '||(c->>k)))),'22023','initial_analysis_input_invalid','noncanonical component '||k) FROM admitted_first CROSS JOIN LATERAL jsonb_object_keys(c) k;
SELECT extensions.throws_ok(format('SELECT pg_temp.admitted_run(%L::JSONB)',jsonb_set(c,ARRAY[k],c->'manifest')),'22023','initial_analysis_input_invalid','swapped component '||k) FROM admitted_first CROSS JOIN LATERAL jsonb_object_keys(c) k WHERE k<>'manifest';
SELECT extensions.throws_ok(format('SELECT internal.parse_initial_admitted_component(%L,%L)',k,repeat(' ',cap+1)),'22023','initial_analysis_input_invalid','cap before parse '||k) FROM (VALUES('candidate',1048576),('input',1048576),('configuration',65563),('funding',4096),('outcome',131072),('installation',16384),('protocol',16384),('destination',16384),('mapping',65536),('media_binding',16384),('accounting',32768),('manifest',8192)) z(k,cap);
SELECT extensions.throws_ok($q$SELECT internal.parse_initial_admitted_component('other','{}')$q$,'22023','initial_analysis_input_invalid','closed component roles');
-- Includes canonically re-committed malformed accounting and schema controls.
CREATE FUNCTION pg_temp.admitted_change_and_run(c JSONB,x JSONB) RETURNS TEXT LANGUAGE PLPGSQL AS $$
DECLARE path TEXT[];
BEGIN
 SELECT array_agg(v ORDER BY i) INTO path FROM jsonb_array_elements_text(x->'path') WITH ORDINALITY z(v,i);
 RETURN pg_temp.admitted_run(pg_temp.admitted_change(c,x->>'component',path,x->'value'));
END; $$;
SELECT extensions.throws_ok(format('SELECT pg_temp.admitted_change_and_run(%L::JSONB,%L::JSONB)',c,x),'22023','initial_analysis_input_invalid','negative vector '||(x->>'name')) FROM admitted_first CROSS JOIN admitted_vectors CROSS JOIN LATERAL jsonb_array_elements(v->'invalid') z(x);
SELECT extensions.throws_ok(format('SELECT pg_temp.admitted_run(%L::JSONB)',jsonb_set(c,'{manifest}',to_jsonb(internal.initial_canonical(jsonb_set((c->>'manifest')::JSONB,ARRAY[k],to_jsonb(repeat('f',64))))))),'22023','initial_analysis_input_invalid','manifest digest '||k) FROM admitted_first CROSS JOIN unnest(ARRAY['assignment_digest','assets_digest','descriptions_digest','phase_window_digest','proof_digest','metadata_digest']) k;
SELECT extensions.throws_ok(format('SELECT pg_temp.admitted_run(%L::JSONB)',pg_temp.admitted_change(c,'accounting','{charges,links}',((c->>'accounting')::JSONB#>'{charges,links}') - 2)),'22023','initial_analysis_input_invalid','missing IP charge') FROM admitted_first;
SELECT extensions.lives_ok(format('SELECT pg_temp.admitted_run(%L::JSONB)',pg_temp.admitted_change(c,'accounting','{charges,links}',((c->>'accounting')::JSONB#>'{charges,links}') - 0)),'optional daily charge absent') FROM admitted_first;
SELECT extensions.throws_ok(format('SELECT pg_temp.admitted_run(%L::JSONB)',pg_temp.admitted_change(c,'accounting','{charges,links}',(SELECT jsonb_agg(x ORDER BY i DESC) FROM jsonb_array_elements((c->>'accounting')::JSONB#>'{charges,links}') WITH ORDINALITY z(x,i)))),'22023','initial_analysis_input_invalid','reordered charges') FROM admitted_first;
SELECT extensions.throws_ok(format('SELECT pg_temp.admitted_run(%L::JSONB)',pg_temp.admitted_change(c,'accounting','{charges,links,1,window_seconds}','3601')),'22023','initial_analysis_input_invalid','rate window above cap') FROM admitted_first;
SELECT extensions.throws_ok(format('SELECT pg_temp.admitted_run(%L::JSONB)',pg_temp.admitted_change(c,'accounting','{charges,links,0,bucket}','" "')),'22023','initial_analysis_input_invalid','ASCII blank bucket') FROM admitted_first;
-- Maximum raw bucket bytes expand beyond the obsolete 16KiB canonical accounting limit.
CREATE TEMP TABLE admitted_escaped AS SELECT pg_temp.admitted_change(pg_temp.admitted_change(pg_temp.admitted_change(c,'accounting','{charges,links,0,bucket}',to_jsonb(repeat(chr(1),1024))),'accounting','{charges,links,1,bucket}',to_jsonb(repeat(chr(1),1024))),'accounting','{charges,links,2,bucket}',to_jsonb(repeat(chr(1),1024))) c FROM admitted_first;
SELECT extensions.ok(octet_length(c->>'accounting')>16384,'escaped accounting exceeds16KiB') FROM admitted_escaped;
SELECT extensions.lives_ok(format('SELECT pg_temp.admitted_run(%L::JSONB)',c),'escaped accounting accepted') FROM admitted_escaped;
SELECT extensions.throws_ok(format('SELECT pg_temp.admitted_run(%L::JSONB)',pg_temp.admitted_change(c,'accounting','{charges,links,0,bucket}',to_jsonb(repeat(chr(1),1025)))),'22023','initial_analysis_input_invalid','raw bucket cap') FROM admitted_escaped;
CREATE TEMP TABLE admitted_timestamps AS SELECT $timestamps${"valid":["0001-01-01T00:00:00.000000Z","2000-02-29T23:59:59.999999Z","9999-12-31T23:59:59.999999Z"],"invalid":["0000-01-01T00:00:00.000000Z","1900-02-29T00:00:00.000000Z","2026-02-29T00:00:00.000000Z","2026-04-31T00:00:00.000000Z","2026-01-00T00:00:00.000000Z","2026-13-01T00:00:00.000000Z","2026-01-01T24:00:00.000000Z","2026-01-01T00:60:00.000000Z","2026-01-01T00:00:60.000000Z","2026-01-01T00:00:00.000Z","2026-01-01T00:00:00.000000+00:00","2026-01-01T00:00:00.000000Z\n","infinity"]}$timestamps$::JSONB v;
SELECT extensions.ok(internal.valid_initial_admitted_timestamp(t),'valid exact timestamp '||t) FROM admitted_timestamps CROSS JOIN LATERAL jsonb_array_elements_text(v->'valid') z(t);
SELECT extensions.ok(NOT internal.valid_initial_admitted_timestamp(t),'invalid exact timestamp '||t) FROM admitted_timestamps CROSS JOIN LATERAL jsonb_array_elements_text(v->'invalid') z(t);
SELECT extensions.throws_ok(format('SELECT pg_temp.admitted_run(%L::JSONB)',pg_temp.admitted_change(c,'accounting',path,to_jsonb(t))),'22023','initial_analysis_input_invalid','timestamp field rejection') FROM admitted_first CROSS JOIN admitted_timestamps CROSS JOIN LATERAL jsonb_array_elements_text(v->'invalid') z(t) CROSS JOIN (VALUES(ARRAY['reservation','lease_expires_at']),(ARRAY['charges','links','0','window_start'])) z2(path);
SELECT extensions.isnt(pg_temp.admitted_run(pg_temp.admitted_change(c,'accounting','{reservation,lease_expires_at}','"2026-10-12T00:20:00.123457Z"')),pg_temp.admitted_run(c),'one microsecond changes receipt') FROM admitted_first;
-- Full proof with independently valid ~1MiB candidate/input must avoid aggregate serialization.
CREATE FUNCTION pg_temp.admitted_large(b JSONB,t TEXT) RETURNS JSONB LANGUAGE PLPGSQL AS $$
DECLARE c JSONB:=(b->>'candidate')::JSONB; descriptions JSONB; timeline JSONB;
BEGIN
 SELECT jsonb_agg(to_jsonb(t)),jsonb_build_array(jsonb_build_object('kind','media','index',0))||jsonb_agg(jsonb_build_object('kind','description','index',i)) INTO descriptions,timeline FROM generate_series(0,15) i;
 c:=jsonb_set(c,'{source_plan,ordered_descriptions}',descriptions);c:=jsonb_set(c,'{source_plan,owner_timeline}',timeline);
 RETURN pg_temp.admitted_rebind(jsonb_set(b,'{candidate}',to_jsonb(internal.initial_canonical(c))));
END; $$;
CREATE TEMP TABLE admitted_large_cases AS SELECT pg_temp.admitted_large(v#>'{valid,1,components}',t) c FROM admitted_vectors CROSS JOIN unnest(ARRAY[repeat('x',65200),'x'||repeat(chr(1),10870)||'x',repeat('🐦',16300)]) t;
SELECT extensions.lives_ok(format('SELECT pg_temp.admitted_run(%L::JSONB)',c),'independent large canonical components') FROM admitted_large_cases;
SELECT extensions.ok((SELECT sum(octet_length(v)) FROM jsonb_each_text(c) z(k,v))>1048576,'retained total above single canonical cap') FROM admitted_large_cases;
-- Complete provider transition proves quota-model versus effective-model separation.
CREATE FUNCTION pg_temp.admitted_openai(b JSONB) RETURNS JSONB LANGUAGE PLPGSQL AS $$
DECLARE c JSONB:=(b->>'candidate')::JSONB; cfg JSONB:=(b->>'configuration')::JSONB; f JSONB:=(b->>'funding')::JSONB; ac JSONB:=(b->>'accounting')::JSONB; k TEXT;
BEGIN
 c:=jsonb_set(c,'{source_plan,admission,expected_processor_permission}','"openai"');
 cfg:=jsonb_set(cfg,'{assignment}',(cfg->'assignment')||'{"provider":"openai","binding":"openai_photo_v1","processor_permission":"openai","provider_model":"gpt-6-sol","effective_model":"gpt-6-sol","minimum_identification_protocol":4}'::JSONB);
 FOREACH k IN ARRAY ARRAY['provider','binding','processor_permission','provider_model','minimum_identification_protocol'] LOOP ac:=jsonb_set(ac,ARRAY['attempt',k],cfg#>ARRAY['assignment',k]); END LOOP;
 f:=jsonb_set(f,'{original,model}','"gpt-6-sol"');
 b:=jsonb_set(b,'{candidate}',to_jsonb(internal.initial_canonical(c)));b:=jsonb_set(b,'{configuration}',to_jsonb(internal.initial_canonical(cfg)));
 b:=jsonb_set(b,'{funding}',to_jsonb(internal.initial_canonical(f)));b:=jsonb_set(b,'{accounting}',to_jsonb(internal.initial_canonical(ac)));
 RETURN pg_temp.admitted_rebind(b);
END; $$;
CREATE TEMP TABLE admitted_openai AS SELECT pg_temp.admitted_openai(v#>'{valid,1,components}') c FROM admitted_vectors;
SELECT extensions.lives_ok(format('SELECT pg_temp.admitted_run(%L::JSONB)',c),'OpenAI effective funding distinct from quota attempt') FROM admitted_openai;
SELECT extensions.throws_ok(format('SELECT pg_temp.admitted_run(%L::JSONB)',pg_temp.admitted_change(c,'funding','{original,model}',(c->>'configuration')::JSONB#>'{assignment,quota_model}')),'22023','initial_analysis_input_invalid','quota model is not returned effective funding') FROM admitted_openai;
SELECT extensions.ok(NOT has_function_privilege(r,s,'EXECUTE'),'denied API helper '||r||s) FROM unnest(ARRAY['anon','authenticated','service_role']) r CROSS JOIN unnest(ARRAY['internal.initial_admitted_proof_schema()','internal.parse_initial_admitted_component(text,text)','internal.valid_initial_admitted_timestamp(text)','internal.validate_initial_admitted_proof(text,text,text,text,text,text,text,text,text,text,text,text)']) s;
SELECT extensions.ok(NOT p.prosecdef AND p.proconfig=ARRAY['search_path=""'] AND p.provolatile IN('i','s'),'pure invoker and fixed search path '||p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='internal' AND p.proname IN('initial_admitted_proof_schema','parse_initial_admitted_component','valid_initial_admitted_timestamp','validate_initial_admitted_proof');
SELECT extensions.is((SELECT initial_analysis_lifecycle_enabled FROM internal.initial_analysis_rollout),FALSE,'activation remains false');
-- Null-safe provider and malformed nested binding values fail closed before casts.
SELECT extensions.throws_ok(format('SELECT pg_temp.admitted_run(%L::JSONB)',pg_temp.admitted_change(c,'media_binding','{phase_window,original_expires_at_ms}','"bad"')),'22023','initial_analysis_input_invalid','malformed expiry rejected before numeric cast') FROM admitted_first;
SELECT extensions.throws_ok(format('SELECT pg_temp.admitted_run(%L::JSONB)',pg_temp.admitted_rebind(pg_temp.admitted_change(c,'configuration','{assignment,provider_model}','null'))),'22023','initial_analysis_input_invalid','OpenAI model cannot be null') FROM admitted_openai;
SELECT extensions.lives_ok(format('SELECT pg_temp.admitted_run(%L::JSONB)',pg_temp.admitted_change(c,'funding','{original,entitlement_version}','9007199254740991')),'largest safe entitlement integer') FROM admitted_first;
-- Every nested mandatory funding/accounting field is closed, even after recommit.
CREATE TEMP TABLE admitted_closed_paths(k,path) AS VALUES ('funding',ARRAY[]::TEXT[]),('funding',ARRAY['original']),('accounting',ARRAY[]::TEXT[]),('accounting',ARRAY['reservation']),('accounting',ARRAY['attempt']),('accounting',ARRAY['charges']),('accounting',ARRAY['charges','policy']),('accounting',ARRAY['charges','links','0']),('accounting',ARRAY['complimentary']);
CREATE FUNCTION pg_temp.admitted_missing(c JSONB,k TEXT,path TEXT[],field TEXT) RETURNS TEXT LANGUAGE PLPGSQL AS $$
DECLARE v JSONB:=(c->>k)::JSONB; target JSONB:=v#>path;
BEGIN
 target:=CASE WHEN field='unexpected' THEN target||'{"unexpected":1}'::JSONB ELSE target-field END;
 v:=CASE WHEN cardinality(path)=0 THEN target ELSE jsonb_set(v,path,target) END;
 RETURN pg_temp.admitted_run(pg_temp.admitted_recommit(jsonb_set(c,ARRAY[k],to_jsonb(internal.initial_canonical(v)))));
END; $$;
SELECT extensions.throws_ok(format('SELECT pg_temp.admitted_missing(%L::JSONB,%L,%L::TEXT[],%L)',c,k,path,field),'22023','initial_analysis_input_invalid','closed accounting/funding '||k||path::TEXT||field) FROM admitted_first CROSS JOIN admitted_closed_paths CROSS JOIN LATERAL (SELECT jsonb_object_keys((c->>k)::JSONB#>path) field UNION ALL SELECT 'unexpected') fields;
-- Privilege catalog assertions above are accompanied by actual role denial.
SELECT extensions.throws_ok(format('SET LOCAL ROLE %I; SELECT %s; RESET ROLE',r,call),'42501',NULL,'actual denied invocation '||r||call) FROM unnest(ARRAY['anon','authenticated','service_role']) r CROSS JOIN unnest(ARRAY['internal.initial_admitted_proof_schema()','internal.parse_initial_admitted_component(NULL,NULL)','internal.valid_initial_admitted_timestamp(NULL)','internal.validate_initial_admitted_proof(NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL)']) call;
SELECT * FROM extensions.finish();
ROLLBACK;
